import{_ as p,c as e,a2 as a,o}from"./chunks/framework.CqbvlPrP.js";const m=JSON.parse('{"title":"第一百零八章 各种界的法义","description":"","frontmatter":{},"headers":[],"relativePath":"meditation/巴利文大藏经/108第一百零八章 各种界的法义.md","filePath":"meditation/巴利文大藏经/108第一百零八章 各种界的法义.md"}'),r={name:"meditation/巴利文大藏经/108第一百零八章 各种界的法义.md"};function _(n,t,i,s,d,c){return o(),e("div",null,t[0]||(t[0]=[a('<h1 id="第一百零八章-各种界的法义" tabindex="-1">第一百零八章 各种界的法义 <a class="header-anchor" href="#第一百零八章-各种界的法义" aria-label="Permalink to &quot;第一百零八章 各种界的法义&quot;">​</a></h1><p>完全读懂巴利文大藏经</p><p>相应部14相应6经/外部的种种界经(界相应/因缘篇/修多罗)</p><p>有个时候，佛陀住在舍卫城的祇树林给孤独园。有一天，佛陀对出家弟子们说：“弟子们，如来现在来为你们讲说种种界的义理，你们要认真的听，你们要仔细的思考，如来现在要开始说法了。”</p><p>出家弟子们回答：“世尊，我们会认真听您说法的，我们会仔细的思考的，恭请世尊您说法。”</p><p>佛陀说：“弟子们，什么是种种界呢？就是各种不同特性的分类。界有：色界、声界、气味界、味道界、所触界、法界。弟子们，这些就被称为种种界。</p><p>弟子们，什么是色界呢？就是有形事物、物质世界的范围。</p><p>什么是声界呢？就是外界声音传播的范围。</p><p>什么是气味界呢？就是外界气味传播的范围。</p><p>什么是味道界呢？就是外界味道传播的范围。</p><p>什么是所触界呢？就是外界能够被触摸、感受到的物质事物、环境（冷热、舒适等等特性）范围。</p><p>什么是法界呢？就是遇见外界事物、思想而生起的各种念想、思想。</p><p>弟子们，这就是种种不同的界。”</p><p>佛陀说法后，听法的出家弟子们都再次的顶礼佛陀，随喜赞叹佛陀说法的无量功德，他们都按着佛陀所说的法去修行。</p>',14)]))}const f=p(r,[["render",_]]);export{m as __pageData,f as default};
